<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('System Administrator','Scholarship Coordinator');
$pageTitle='Stipend Records';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!verify_csrf_token($_POST['csrf_token']??null))throw new RuntimeException('Invalid request. Refresh the page.');
  $app=filter_var($_POST['scholarship_application_id']??null,FILTER_VALIDATE_INT);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$date=($_POST['release_date']??'')?:null;$recipient=trim($_POST['recipient_name']??'');$status=$_POST['claiming_status']??'Pending Claim';$remarks=trim($_POST['remarks']??'');
  if(!$app||$amount===false||$amount<=0||$recipient===''||strlen($recipient)>150||!in_array($status,['Pending Claim','Claimed','Unclaimed'],true))throw new RuntimeException('Enter a valid scholar, positive amount, recipient, and claiming status.');
  if($date!==null&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Enter a valid release date.');
  $check=$pdo->prepare("SELECT scholarship_application_id FROM scholarship_applications WHERE scholarship_application_id=:id AND application_status='Approved'");$check->execute(['id'=>$app]);if(!$check->fetch())throw new RuntimeException('Stipends can only be recorded for approved scholarship applications.');
  $q=$pdo->prepare('INSERT INTO stipend_records(scholarship_application_id,amount,release_date,recipient_name,claiming_status,remarks,recorded_by) VALUES(:app,:amount,:date,:recipient,:status,:remarks,:user)');
  $q->execute(['app'=>$app,'amount'=>$amount,'date'=>$date,'recipient'=>$recipient,'status'=>$status,'remarks'=>$remarks?:null,'user'=>current_user()['user_id']]);$success='Stipend record saved.';
 }catch(PDOException $ex){error_log('Stipend records: '.$ex->getMessage());$error='Unable to save the stipend record.';}catch(RuntimeException $ex){$error=$ex->getMessage();}
}
$approved=$pdo->query("SELECT sa.scholarship_application_id,st.first_name,st.last_name,sp.program_name,y.school_year FROM scholarship_applications sa JOIN students st ON st.student_id=sa.student_id JOIN special_programs sp ON sp.program_id=sa.program_id JOIN school_years y ON y.school_year_id=sa.school_year_id WHERE sa.application_status='Approved' ORDER BY st.last_name,st.first_name")->fetchAll();
$records=$pdo->query("SELECT sr.*,st.first_name,st.last_name,sp.program_name FROM stipend_records sr JOIN scholarship_applications sa ON sa.scholarship_application_id=sr.scholarship_application_id JOIN students st ON st.student_id=sa.student_id JOIN special_programs sp ON sp.program_id=sa.program_id ORDER BY sr.release_date DESC,sr.stipend_id DESC")->fetchAll();
require_once __DIR__.'/../includes/header.php';
?>
<section class="form-card form-card-wide"><h1>Stipend Records</h1><p class="muted">Record and track stipend releases for approved scholarship recipients.</p><?php if($success):?><p class="success-message"><?=e($success)?></p><?php endif;?><?php if($error):?><p class="error-message"><?=e($error)?></p><?php endif;?>
<h2>Add Stipend Record</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Approved scholar<select name="scholarship_application_id" required><option value="">Select scholar</option><?php foreach($approved as $a):?><option value="<?=(int)$a['scholarship_application_id']?>"><?=e($a['last_name'].', '.$a['first_name'].' — '.$a['program_name'].' ('.$a['school_year'].')')?></option><?php endforeach;?></select></label><label>Amount<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Release date<input type="date" name="release_date"></label><label>Recipient name<input name="recipient_name" maxlength="150" required></label><label>Claiming status<select name="claiming_status"><option>Pending Claim</option><option>Claimed</option><option>Unclaimed</option></select></label><label>Remarks<textarea name="remarks" rows="2"></textarea></label><button class="button button-primary">Save Stipend</button></form>
<h2>Stipend History</h2><div class="table-responsive"><table><thead><tr><th>Recipient</th><th>Program</th><th>Amount</th><th>Release Date</th><th>Claiming Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=e($r['recipient_name'])?><br><small><?=e($r['first_name'].' '.$r['last_name'])?></small></td><td><?=e($r['program_name'])?></td><td>₱<?=number_format((float)$r['amount'],2)?></td><td><?=e($r['release_date']??'Not scheduled')?></td><td><?=e($r['claiming_status'])?></td><td><?=e($r['remarks']??'')?></td></tr><?php endforeach;?><?php if(!$records):?><tr><td colspan="6">No stipend records yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php require_once __DIR__.'/../includes/footer.php';?>
